using Microsoft.Data.Sqlite; using Microsoft.EntityFrameworkCore; using SalesManagement.Core.Models; using SalesManagement.Postgres; using SalesManagement.Postgres.Repositories;
namespace SalesManagement.DbTests;
public sealed class QuotationInquiryDatabaseTests
{
    [Fact] public async Task Persists_inquiry_attachment_quote_graph_and_incoterm()
    {
        await using var connection = new SqliteConnection("DataSource=:memory:"); await connection.OpenAsync(); var options = new DbContextOptionsBuilder<SalesDbContext>().UseSqlite(connection).Options; await using var db = new SalesDbContext(options); await db.Database.EnsureCreatedAsync();
        var user = new User { LoginId = "manager", PasswordHash = "hash", Name = "이재학", Email = "jhlee@switchkorea.com", Role = Role.Manager }; var customer = new Customer { Code = "C1", CompanyName = "거래처", Country = "KR", DefaultCurrency = Currency.KRW, OwnerUserId = user.Id }; var product = new Product { Code = "P1", Name = "스위치", ItemType = ItemType.Product }; db.AddRange(user, customer, product); await db.SaveChangesAsync();
        var inquiryRepo = new InquiryRepository(db); var inquiry = new CustomerInquiry { InquiryNumber = "INQ-202610-001", Title = "문의", CustomerId = customer.Id, CustomerName = customer.CompanyName, ContactName = "김담당", OwnerUserId = user.Id, ReceivedAt = new(2026,10,8), ResponseDueAt = new(2026,10,10), Summary = "사양 문의" }; inquiry.Attachments.Add(new InquiryAttachment { InquiryId = inquiry.Id, FileName = "spec.pdf", ContentType = "application/pdf", Content = [1,2,3], Size = 3, UploadedBy = user.Id, UploadedAt = DateTimeOffset.UtcNow }); await inquiryRepo.AddAsync(inquiry); Assert.Equal(3, (await inquiryRepo.GetAsync(inquiry.Id))!.Attachments.Single().Content.Length);
        var quoteRepo = new QuoteRepository(db); var quote = new Quote { QuoteNumber = "SWK-202610-001", InquiryId = inquiry.Id, CustomerId = customer.Id, CustomerName = customer.CompanyName, OwnerUserId = user.Id }; var revision = new QuoteRevision { QuoteId = quote.Id, RevisionNumber = 0, Currency = Currency.KRW, TradeType = QuoteTradeType.Domestic, TaxType = QuoteTaxType.Exclusive, ValidUntil = new(2026,10,31), SubtotalAmount = 100, SupplyAmount = 100, TaxAmount = 10, TotalAmount = 110 }; revision.Lines.Add(new QuoteLine { RevisionId = revision.Id, ProductId = product.Id, Description = product.Name, Quantity = 1, UnitPrice = 100, Amount = 100 }); quote.Revisions.Add(revision); quote.CurrentRevisionId = revision.Id; await quoteRepo.AddAsync(quote); var savedQuote = (await quoteRepo.GetAsync(quote.Id))!; Assert.Equal(110, savedQuote.Revisions.Single().TotalAmount); savedQuote.Revisions.Single().Status = QuoteStatus.ApprovalRequested; savedQuote.Revisions.Single().Approvals.Add(new QuoteApproval { RevisionId = revision.Id, RequestedBy = user.Id, RequestedAt = DateTimeOffset.UtcNow, Decision = QuoteApprovalDecision.Pending }); await quoteRepo.UpdateAsync(savedQuote, savedQuote.Version); Assert.Single((await quoteRepo.GetAsync(quote.Id))!.Revisions.Single().Approvals);
        var termRepo = new IncotermRepository(db); await termRepo.AddAsync(new Incoterm { Code = "CIF", DisplayName = "Cost Insurance Freight", SortOrder = 10 }); Assert.NotNull(await termRepo.FindByCodeAsync("cif")); Assert.Equal(1, await quoteRepo.NextSequenceAsync(2026, 10)); Assert.Equal(2, await quoteRepo.NextSequenceAsync(2026, 10));
    }
}
